#include <bits/stdc++.h>
using namespace std;
#define ll long long
const int maxn = 505;
int n, m, mod;
inline int add(int x, int y) {
    int res = x + y;
    return res >= mod ? res - mod : res;
}
inline int mul(int x, int y) { return (ll) x * y % mod; }
int C[maxn][maxn];
int f[maxn], g[maxn];
int F[maxn][maxn], G[maxn][maxn];

int main() {
    scanf("%d%d%d", &n, &m, &mod);
    for (int i = 0; i <= n; i++) {
        C[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            C[i][j] = add(C[i - 1][j - 1], C[i - 1][j]);
        }
    }
    f[0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            int term1 = mul(mul(f[j - 1], f[i - j]), mul(i + 1, C[i - 1][j - 1]));
            f[i] = add(f[i], term1);
            int term2 = mul(mul(f[j - 1], g[i - j]), mul(i + 1, C[i - 1][j - 1]));
            g[i] = add(g[i], term2);
            int term3 = mul(mul(g[j - 1], f[i - j]), mul(i + 1, C[i - 1][j - 1]));
            g[i] = add(g[i], term3);
            int term4 = mul(mul(f[j - 1], f[i - j]), mul(add(C[j][2], C[i - j + 1][2]), C[i - 1][j - 1]));
            g[i] = add(g[i], term4);
        }
    }
    F[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        F[i][i] = f[i];
        G[i][i] = g[i];
        for (int j = 0; j <= min(i - 1, m); j++) {
            for (int l = 0; l <= j; l++) {
                int val1 = mul(mul(f[l], F[i - l - 1][j - l]), C[j][l]);
                F[i][j] = add(F[i][j], val1);
                int val2 = mul(mul(g[l], F[i - l - 1][j - l]), C[j][l]);
                G[i][j] = add(G[i][j], val2);
                int val3 = mul(mul(f[l], G[i - l - 1][j - l]), C[j][l]);
                G[i][j] = add(G[i][j], val3);
            }
        }
    }
    cout << G[n][m] << endl;
    return 0;
}
